// Fixed-category output only. Never return raw responses, headers, phone, OTP or keys.
function inspect(name,kind){
  const raw=$(name).first().json;
  const status=Number.isInteger(raw.statusCode)?raw.statusCode:null;
  const body=raw.body??raw.data;
  const content=typeof body==='string'?body:JSON.stringify(body??{});
  let parsed=null;try{parsed=typeof body==='string'?JSON.parse(body):body;}catch{}
  const text=(content+' '+JSON.stringify(raw.error??'')).slice(0,20000).toLowerCase();
  let reason='unclassified_response';
  if(status===null){
    if(/not.*allowed|allow.*domain|domain.*restrict/.test(text))reason='credential_domain_restriction';
    else if(/credential/.test(text))reason='credential_missing_or_unavailable';
    else if(/timed?\s*out|etimedout|timeout/.test(text))reason='request_timeout';
    else if(/enotfound|eai_again|dns/.test(text))reason='dns_error';
    else if(/certificate|tls|ssl/.test(text))reason='tls_error';
    else reason='transport_or_node_error';
  }else if(status===401)reason='authentication_rejected';
  else if(status===403){
    if(/scope|permission/.test(text))reason='permission_or_scope_rejected';
    else if(/balance|credit|fund/.test(text))reason='balance_related_rejection';
    else reason='forbidden';
  }else if(status===404)reason='resource_not_found_or_not_visible';
  else if(status===429)reason='rate_limited';
  else if(status>=500)reason='server_or_gateway_error';
  else if(kind==='empty_payload'&&[400,422].includes(status))reason='empty_payload_rejected_expected';
  else if(kind==='empty_payload'&&status>=200&&status<300)reason='unexpected_success_investigate';
  else if(kind==='database_read'&&status===200&&Array.isArray(parsed)&&parsed.length===0)reason='database_read_access_ok';
  else if(kind==='message_read'&&status===200&&parsed?.success!==false&&['pending','queued','sent','delivered','read','failed','rejected','cancelled'].includes((parsed?.data??parsed)?.status))reason='existing_message_read_access_ok';
  else if(status>=200&&status<300)reason='http_success_content_unverified';
  else if(status>=300&&status<400)reason='redirect_not_followed';
  else if(status===400)reason='bad_request';
  return {http_status:status,result:reason,response_format:parsed===null?'non_json_or_unavailable':'json'};
}
return [{json:{
  check:'Proxo credential diagnostics - no OTP send',
  checked_at_utc:new Date().toISOString(),
  Supabase:inspect('Supabase read check','database_read'),
  Wevlix_read:inspect('Wevlix read check','message_read'),
  Wevlix_empty_request:inspect('Wevlix empty request','empty_payload'),
  valid_send_tested:false,
  previous_live_attempt_resolved:false,
  note:'Only table access, an existing message lookup, and a deliberately empty request were checked. This does not verify valid-message sending, template eligibility, balance, delivery or the earlier 502.'
}}];
